package com.cpf.starter.tcp;import java.io.*;import java.net.*;import java.time.Instant;import java.util.concurrent.ArrayBlockingQueue;import javax.net.SocketFactory;import javax.net.ssl.SSLSocketFactory;
public final class CpfTcpClient implements AutoCloseable {private final CpfTcpProperties p;private final CpfTcpFrameCodec codec;private final ArrayBlockingQueue<Socket> pool;private final CpfTcpUnknownResultStore unknown;private final CpfTcpTlsContextProvider tls;
 public CpfTcpClient(CpfTcpProperties p,CpfTcpUnknownResultStore u,CpfTcpTlsContextProvider tls){this.p=p;codec=new CpfTcpFrameCodec(p);pool=new ArrayBlockingQueue<>(p.getPoolSize());unknown=u;this.tls=tls;}
 public byte[] request(String correlationId,byte[] payload){Socket s=null;boolean written=false;try{s=borrow();s.setSoTimeout((int)p.getResponseTimeout().toMillis());codec.write(s.getOutputStream(),payload);written=true;byte[] response=codec.read(s.getInputStream());release(s);return response;}catch(SocketTimeoutException|EOFException ex){destroy(s);if(written)unknown.record(new CpfTcpUnknownResult(correlationId,Instant.now(),payload,ex.getClass().getSimpleName()));throw new UnknownResultException(correlationId,ex);}catch(IOException ex){destroy(s);if(written){unknown.record(new CpfTcpUnknownResult(correlationId,Instant.now(),payload,ex.getMessage()));throw new UnknownResultException(correlationId,ex);}throw new IllegalStateException("TCP request failed before write",ex);}}
 private Socket borrow()throws IOException{Socket s=pool.poll();if(s!=null&&s.isConnected()&&!s.isClosed())return s;SocketFactory f=p.isTls()?tls.current().getSocketFactory():SocketFactory.getDefault();s=f.createSocket();s.connect(new InetSocketAddress(p.getHost(),p.getPort()),(int)p.getConnectTimeout().toMillis());return s;}private void release(Socket s){if(!pool.offer(s))destroy(s);}private static void destroy(Socket s){if(s!=null)try{s.close();}catch(IOException ignored){}}public void close(){Socket s;while((s=pool.poll())!=null)destroy(s);}public static final class UnknownResultException extends RuntimeException{private final String correlationId;public UnknownResultException(String id,Throwable c){super("TCP UNKNOWN_RESULT: "+id,c);correlationId=id;}public String correlationId(){return correlationId;}}}
